-- Dadyoom Grade 1-3 original supplementary text-linked exercises: قراءة نص قصير, 66 safe lesson IDs.
-- The independently authored reading passages reside in each activity's content.originalText (visible to the learner).
-- No ministry source equivalence, audio delivery, or teacher sign-off is inferred. Existing learner attempts are preserved.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='90s';
CREATE TEMP TABLE g123_reading_activities ON COMMIT DROP AS
SELECT grade::int,activity_order::int,activity_type::text,title::text,section::text,prompt::text,content::jsonb,answer::jsonb
FROM jsonb_to_recordset($passage$[{"grade":1,"activity_order":4,"activity_type":"fill_blank","title":"تطبيق موجه على النص","section":"practice","prompt":"أين شاهدت سلمى العصفور؟","content":{"origin":"DADYOOM_G123_READING_198_ORIGINAL_20261030","originalText":"ذهبت سلمى مع أبيها إلى الحديقة. شاهدت عصفورًا قرب الشجرة. وضعت ماءً في إناء صغير بعيدًا عن الطريق، ثم جلست تراقب العصفور من مسافة آمنة. فرحت سلمى عندما شرب العصفور، وتعلمت أن الرفق بالحيوان سلوك جميل. النص يتحدث عن سلمى وعصفور في الحديقة.","didacticGrade":1,"scope":"original supplementary reading","items":[{"sentence":"شاهدت سلمى العصفور قرب ___.","options":["الشجرة","السبورة","المكتبة"]}]},"answer":{"answers":["الشجرة"]}},{"grade":1,"activity_order":5,"activity_type":"matching","title":"توصيل المفهوم بالدليل","section":"practice","prompt":"اقرأ النص الإثرائي ثم صِل كل عبارة بما تمثله من حدث أو معلومة أو وظيفة.","content":{"origin":"DADYOOM_G123_READING_198_ORIGINAL_20261030","originalText":"ذهبت سلمى مع أبيها إلى الحديقة. شاهدت عصفورًا قرب الشجرة. وضعت ماءً في إناء صغير بعيدًا عن الطريق، ثم جلست تراقب العصفور من مسافة آمنة. فرحت سلمى عندما شرب العصفور، وتعلمت أن الرفق بالحيوان سلوك جميل. النص يتحدث عن سلمى وعصفور في الحديقة.","didacticGrade":1,"scope":"original supplementary reading","left":["سلمى","الحديقة","الماء"],"right":["ما قدمته للعصفور","الشخصية الرئيسة","مكان الحدث"]},"answer":{"pairs":[{"left":"سلمى","right":"الشخصية الرئيسة"},{"left":"الحديقة","right":"مكان الحدث"},{"left":"الماء","right":"ما قدمته للعصفور"}]}},{"grade":1,"activity_order":6,"activity_type":"multiple_choice","title":"تقييم الفهم والاستنتاج","section":"assessment","prompt":"ما السلوك الجميل الذي تظهره القصة؟","content":{"origin":"DADYOOM_G123_READING_198_ORIGINAL_20261030","originalText":"ذهبت سلمى مع أبيها إلى الحديقة. شاهدت عصفورًا قرب الشجرة. وضعت ماءً في إناء صغير بعيدًا عن الطريق، ثم جلست تراقب العصفور من مسافة آمنة. فرحت سلمى عندما شرب العصفور، وتعلمت أن الرفق بالحيوان سلوك جميل. النص يتحدث عن سلمى وعصفور في الحديقة.","didacticGrade":1,"scope":"original supplementary reading","options":["إخافة العصافير","الرفق بالحيوان وتقديم الماء بأمان","إلقاء القمامة في الحديقة"]},"answer":{"correct":"الرفق بالحيوان وتقديم الماء بأمان"}},{"grade":2,"activity_order":4,"activity_type":"fill_blank","title":"تطبيق موجه على النص","section":"practice","prompt":"ما معنى «واقٍ» في وصف الغلاف الورقي حسب سياق القصة؟","content":{"origin":"DADYOOM_G123_READING_198_ORIGINAL_20261030","originalText":"في الصباح، رأى مالك كتابًا قديمًا على طاولة الصف وقد تمزقت زاوية غلافه. أخبر معلمته بالأمر، ثم ساعد زميله في وضع غلاف ورقي واقٍ حول الكتاب دون إخفاء عنوانه. أعادا الكتاب إلى الرف المخصص للقراءة المشتركة. شكرتهما المعلمة، وقالت إن المحافظة على الكتب تجعلها صالحة لجميع التلاميذ. تبرز القصة معنى التعاون والمسؤولية تجاه الممتلكات المشتركة.","didacticGrade":2,"scope":"original supplementary reading","items":[{"sentence":"الغلاف الورقي ___ يحمي الكتاب من التلف.","options":["الواقي","الزائد","الممزق"]}]},"answer":{"answers":["الواقي"]}},{"grade":2,"activity_order":5,"activity_type":"matching","title":"توصيل المفهوم بالدليل","section":"practice","prompt":"اقرأ النص الإثرائي ثم صِل كل عبارة بما تمثله من حدث أو معلومة أو وظيفة.","content":{"origin":"DADYOOM_G123_READING_198_ORIGINAL_20261030","originalText":"في الصباح، رأى مالك كتابًا قديمًا على طاولة الصف وقد تمزقت زاوية غلافه. أخبر معلمته بالأمر، ثم ساعد زميله في وضع غلاف ورقي واقٍ حول الكتاب دون إخفاء عنوانه. أعادا الكتاب إلى الرف المخصص للقراءة المشتركة. شكرتهما المعلمة، وقالت إن المحافظة على الكتب تجعلها صالحة لجميع التلاميذ. تبرز القصة معنى التعاون والمسؤولية تجاه الممتلكات المشتركة.","didacticGrade":2,"scope":"original supplementary reading","left":["مالك","الغلاف الورقي الواقي","رف القراءة المشتركة"],"right":["مكان إعادة الكتاب","الشخص الذي لاحظ تلف الغلاف","وسيلة حماية الكتاب"]},"answer":{"pairs":[{"left":"مالك","right":"الشخص الذي لاحظ تلف الغلاف"},{"left":"الغلاف الورقي الواقي","right":"وسيلة حماية الكتاب"},{"left":"رف القراءة المشتركة","right":"مكان إعادة الكتاب"}]}},{"grade":2,"activity_order":6,"activity_type":"multiple_choice","title":"تقييم الفهم والاستنتاج","section":"assessment","prompt":"أي دليل في النص يعبّر عن التعاون؟","content":{"origin":"DADYOOM_G123_READING_198_ORIGINAL_20261030","originalText":"في الصباح، رأى مالك كتابًا قديمًا على طاولة الصف وقد تمزقت زاوية غلافه. أخبر معلمته بالأمر، ثم ساعد زميله في وضع غلاف ورقي واقٍ حول الكتاب دون إخفاء عنوانه. أعادا الكتاب إلى الرف المخصص للقراءة المشتركة. شكرتهما المعلمة، وقالت إن المحافظة على الكتب تجعلها صالحة لجميع التلاميذ. تبرز القصة معنى التعاون والمسؤولية تجاه الممتلكات المشتركة.","didacticGrade":2,"scope":"original supplementary reading","options":["ترك مالك الكتاب ممزقًا.","إخبار المعلمة دون أي عمل آخر.","مساعدة مالك وزميله في حماية الكتاب وإعادته إلى الرف."]},"answer":{"correct":"مساعدة مالك وزميله في حماية الكتاب وإعادته إلى الرف."}},{"grade":3,"activity_order":4,"activity_type":"fill_blank","title":"تطبيق موجه على النص","section":"practice","prompt":"لماذا سجّل الطلاب كمية الورق قبل التجربة وبعدها؟","content":{"origin":"DADYOOM_G123_READING_198_ORIGINAL_20261030","originalText":"أراد طلاب الصف الثالث تقليل هدر الورق في الأنشطة اليومية. راقبوا كمية الأوراق المستخدمة خلال خمسة أيام، فوجدوا أن بعض الصفحات يُكتب عليها من جهة واحدة فقط. اقترحوا تخصيص صندوق للأوراق النظيفة من الوجه الآخر لاستخدامها في المسودات، ووضعوا تعليمات واضحة قربه. في الأسبوع التالي، لاحظوا أن عدد الأوراق الجديدة المستهلكة انخفض. سجّل الطلاب القياس قبل التجربة وبعدها؛ حتى يميزوا بين توقع نجاح الفكرة والدليل الذي يؤكد أثرها. توضح القصة قيمة التخطيط والتحقق من النتائج.","didacticGrade":3,"scope":"original supplementary reading","items":[{"sentence":"سجّل الطلاب الأرقام ليقارنوا الاستهلاك ويعرفوا ___ الحل.","options":["أثر","لون","عنوان"]}]},"answer":{"answers":["أثر"]}},{"grade":3,"activity_order":5,"activity_type":"matching","title":"توصيل المفهوم بالدليل","section":"practice","prompt":"اقرأ النص الإثرائي ثم صِل كل عبارة بما تمثله من حدث أو معلومة أو وظيفة.","content":{"origin":"DADYOOM_G123_READING_198_ORIGINAL_20261030","originalText":"أراد طلاب الصف الثالث تقليل هدر الورق في الأنشطة اليومية. راقبوا كمية الأوراق المستخدمة خلال خمسة أيام، فوجدوا أن بعض الصفحات يُكتب عليها من جهة واحدة فقط. اقترحوا تخصيص صندوق للأوراق النظيفة من الوجه الآخر لاستخدامها في المسودات، ووضعوا تعليمات واضحة قربه. في الأسبوع التالي، لاحظوا أن عدد الأوراق الجديدة المستهلكة انخفض. سجّل الطلاب القياس قبل التجربة وبعدها؛ حتى يميزوا بين توقع نجاح الفكرة والدليل الذي يؤكد أثرها. توضح القصة قيمة التخطيط والتحقق من النتائج.","didacticGrade":3,"scope":"original supplementary reading","left":["ملاحظة استعمال بعض الصفحات من جهة واحدة.","تخصيص صندوق لأوراق المسودات.","انخفاض الأوراق الجديدة المستهلكة."],"right":["نتيجة مدعومة بالملاحظة","مشكلة أو ملاحظة أولية","إجراء عملي مقترح"]},"answer":{"pairs":[{"left":"ملاحظة استعمال بعض الصفحات من جهة واحدة.","right":"مشكلة أو ملاحظة أولية"},{"left":"تخصيص صندوق لأوراق المسودات.","right":"إجراء عملي مقترح"},{"left":"انخفاض الأوراق الجديدة المستهلكة.","right":"نتيجة مدعومة بالملاحظة"}]}},{"grade":3,"activity_order":6,"activity_type":"multiple_choice","title":"تقييم الفهم والاستنتاج","section":"assessment","prompt":"ما الدليل الذي يساند الاستنتاج أن خطة الصف قللت استهلاك الورق؟","content":{"origin":"DADYOOM_G123_READING_198_ORIGINAL_20261030","originalText":"أراد طلاب الصف الثالث تقليل هدر الورق في الأنشطة اليومية. راقبوا كمية الأوراق المستخدمة خلال خمسة أيام، فوجدوا أن بعض الصفحات يُكتب عليها من جهة واحدة فقط. اقترحوا تخصيص صندوق للأوراق النظيفة من الوجه الآخر لاستخدامها في المسودات، ووضعوا تعليمات واضحة قربه. في الأسبوع التالي، لاحظوا أن عدد الأوراق الجديدة المستهلكة انخفض. سجّل الطلاب القياس قبل التجربة وبعدها؛ حتى يميزوا بين توقع نجاح الفكرة والدليل الذي يؤكد أثرها. توضح القصة قيمة التخطيط والتحقق من النتائج.","didacticGrade":3,"scope":"original supplementary reading","options":["انخفاض عدد الأوراق الجديدة في الأسبوع التالي.","تسمية الصندوق باسم جميل.","رغبة الطلاب في النجاح دون قياس."]},"answer":{"correct":"انخفاض عدد الأوراق الجديدة في الأسبوع التالي."}}]$passage$::jsonb)
AS x(grade int,activity_order int,activity_type text,title text,section text,prompt text,content jsonb,answer jsonb);
DO $safe$
DECLARE candidates int; safe_candidates int; protected_count int; inserted int;
BEGIN
 IF (SELECT count(*) FROM pg_temp.g123_reading_activities)<>9 OR
    (SELECT count(DISTINCT (grade,activity_order)) FROM pg_temp.g123_reading_activities)<>9 OR
    EXISTS(SELECT 1 FROM pg_temp.g123_reading_activities WHERE activity_type IS NULL OR answer IS NULL OR length(content->>'originalText')<150)
 THEN RAISE EXCEPTION 'Invalid nine source-linked grade-specific templates'; END IF;
 WITH found AS (
  SELECT l.id,count(a.id) FILTER(WHERE a.is_published) n,
    count(DISTINCT a.activity_order) positions,max(a.activity_order) max_order
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
  LEFT JOIN public.lesson_activities a ON a.lesson_id=l.id
  WHERE l.title='قراءة نص قصير' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3 AND l.content LIKE '%النص%' AND length(l.content)>=500
  GROUP BY l.id
 )
 SELECT count(*) INTO candidates FROM found WHERE n=3 AND positions=3 AND max_order=3;
 IF candidates<>66 THEN RAISE EXCEPTION 'Expected 66 original lesson IDs with three existing activities, found %',candidates; END IF;
 SELECT count(*) INTO protected_count FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 WHERE l.title='قراءة نص قصير' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3 AND l.content LIKE '%النص%' AND length(l.content)>=500 AND NOT (NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities la ON la.id=at.activity_id WHERE la.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id));
 IF protected_count<>0 THEN RAISE EXCEPTION 'Protected learner-history count drift, expected 0, found %', protected_count; END IF;
 SELECT count(*) INTO safe_candidates FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 WHERE l.title='قراءة نص قصير' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3 AND l.content LIKE '%النص%' AND length(l.content)>=500 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities la ON la.id=at.activity_id WHERE la.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 IF safe_candidates<>66 THEN RAISE EXCEPTION 'Expected 66 safe lesson IDs, got %',safe_candidates; END IF;
 IF EXISTS (SELECT 1 FROM public.lesson_activities a WHERE a.content->>'origin'='DADYOOM_G123_READING_198_ORIGINAL_20261030')
 THEN RAISE EXCEPTION 'Batch DADYOOM_G123_READING_198_ORIGINAL_20261030 already inserted'; END IF;
 INSERT INTO public.lesson_activities
  (lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
 SELECT l.id,t.title,t.activity_type,'اقرأ النص الإثرائي الموجود داخل النشاط؛ اقرأ محتوى درس بلدك مستقلًا.',
        t.content,t.activity_order,5,true,t.section,t.prompt,t.answer,false
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN pg_temp.g123_reading_activities t ON t.grade=g.grade_number
 WHERE l.title='قراءة نص قصير' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3 AND l.content LIKE '%النص%' AND length(l.content)>=500 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities la ON la.id=at.activity_id WHERE la.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>198 THEN RAISE EXCEPTION 'Atomic rollback: inserted % instead of 198',inserted; END IF;
 RAISE NOTICE 'DADYOOM_G123_READING_198_ORIGINAL_20261030=%',inserted;
END $safe$;
COMMIT;
